CREATE POLICY "visual_refs_insert_own_task" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'visual-references' AND (storage.foldername(name))[1] = auth.uid()::text AND EXISTS (SELECT 1 FROM public.agent_sessions s WHERE s.id::text = (storage.foldername(name))[2] AND s.user_id = auth.uid()));
CREATE POLICY "visual_refs_read_own_task" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'visual-references' AND (storage.foldername(name))[1] = auth.uid()::text AND EXISTS (SELECT 1 FROM public.agent_sessions s WHERE s.id::text = (storage.foldername(name))[2] AND s.user_id = auth.uid()));
CREATE POLICY "visual_refs_delete_own_task" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'visual-references' AND (storage.foldername(name))[1] = auth.uid()::text AND EXISTS (SELECT 1 FROM public.agent_sessions s WHERE s.id::text = (storage.foldername(name))[2] AND s.user_id = auth.uid()));